insert into hm_texts (key, label, value, sort) values
('phone','Телефон (везде на сайте и для WhatsApp)','8 963 599-36-01',1),
('hero_lead','Главный экран — текст под заголовком','Вешаю люстры и телевизоры, собираю шкафы и кухни, меняю смесители, кладу ламинат. Занимаюсь этим пять лет, живу в Грозном. Позвоните, расскажите, что случилось, — скажу, сколько стоит и когда смогу приехать.',2),
('hero_why','Главный экран — что такое Handyman (**жирный**)','**Handyman** — так в Америке называют мастера, к которому идут с любой домашней поломкой. Один человек вместо пяти разных. В Грозном такой тоже есть.',3),
('spec_lead','Услуги — подзаголовок','Список длинный, потому что дома ломается всё подряд. Если вашей задачи тут нет — всё равно спросите.',4),
('tf_lead','Комната «от и до» — текст','Облезлый линолеум, старый стеллаж, пустые стены. Листайте — увидите, что стало.',5),
('cases_lead','Кейсы — подзаголовок','Фото с телефона, прямо с объектов. Без обработки «как в журнале» — как есть.',6),
('master_lead','«Это я» — текст','Мне 21, руками работаю с шестнадцати. Работаю один: трубку беру я, приезжаю тоже я.',7),
('p_age','Паспорт — возраст','21 год',8),
('p_from','Паспорт — родом из','Грозный — родился и живу здесь',9),
('p_exp','Паспорт — стаж','5 лет в ремонте',10),
('p_skills','Паспорт — умеет','Электрика, сантехника, мебель, полы, двери, слаботочка',11),
('p_area','Паспорт — выезд','Грозный и ближайшие районы',12),
('r1_t','Как я работаю — 1, заголовок','Цена — до начала',13),
('r1_p','Как я работаю — 1, текст','Скидываете фото, называю цифру. Если на месте вылезет что-то ещё, сначала скажу, потом делаю.',14),
('r2_t','Как я работаю — 2, заголовок','Инструмент свой',15),
('r2_p','Как я работаю — 2, текст','Перфоратор, уровень, стремянка — всё привожу. Искать дрель по соседям не придётся.',16),
('r3_t','Как я работаю — 3, заголовок','Убираю за собой',17),
('r3_p','Как я работаю — 3, текст','Пыль от сверления, коробки и плёнку от мебели — забираю или складываю, куда скажете.',18),
('r4_t','Как я работаю — 4, заголовок','Если что-то не так',19),
('r4_p','Как я работаю — 4, текст','Звоните. Приеду и переделаю — без споров, чья вина.',20),
('order_lead','Наряд — подзаголовок','Отметьте задачи и нажмите кнопку — откроется WhatsApp с готовым сообщением. Фото киньте туда же, так быстрее посчитаю.',21),
('faq1_q','Вопрос 1','Сколько стоит работа?',22),
('faq1_a','Ответ 1','Зависит от задачи: розетка и кухня стоят по-разному. Пришлите фото в WhatsApp — назову цену до начала. Если на месте окажется сложнее, скажу об этом до того, как начну.',23),
('faq2_q','Вопрос 2','Как быстро приедете?',24),
('faq2_a','Ответ 2','Зависит от загрузки. Позвоните — скажу честно, когда смогу. Если срочно — например, течёт — так и скажите.',25),
('faq3_q','Вопрос 3','Работаете за пределами Грозного?',26),
('faq3_a','Ответ 3','Да, выезжаю в ближайшие районы. Напишите адрес — скажу, когда смогу приехать.',27),
('faq4_q','Вопрос 4','Материалы покупать мне?',28),
('faq4_a','Ответ 4','Обычно покупаете вы — я скажу, что именно взять, чтобы не ездить в магазин дважды.',29),
('faq5_q','Вопрос 5','Можно несколько работ за раз?',30),
('faq5_a','Ответ 5','Да, и так даже лучше. Отметьте всё сразу — сделаю за один приезд, а не за три.',31),
('final_area','Низ страницы — подпись','ГРОЗНЫЙ И БЛИЖАЙШИЕ РАЙОНЫ · ЕСЛИ НЕ ВЗЯЛ ТРУБКУ — ЗНАЧИТ, НА ОБЪЕКТЕ, ПЕРЕЗВОНЮ',32)
